#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin>>n; vector<long long>a(n); for(auto&x:a)cin>>x;
    long long prev=0, mx=0;                    // prev = final height of previous segment
    for(int i=0;i<n;i++){
        long long b = (i==0)? a[i] : min(a[i], prev-1); // keep as high as allowed
        mx = max(mx, a[i]-b);                  // how much segment i must be lowered
        prev = b;
    }
    int days=0; while(mx>0){days++; mx>>=1;}  // bit length of largest reduction
    cout<<days<<"\n";
}

