using namespace std;
int main(){
    int n; cin>>n; vector<long long>a(n); for(auto&x:a)cin>>x;
    int l=0,r=n-1; long long last=LLONG_MIN; string s;
    while(l<=r){
        bool cl=a[l]>last, cr=a[r]>last;
        if(l<r && cl && cr && a[l]==a[r]){
            int x=1; while(l+x<=r && a[l+x]>a[l+x-1]) x++;
            int y=1; while(r-y>=l && a[r-y]>a[r-y+1]) y++;
            s+= x>=y ? string(x,'L') : string(y,'R'); break;
        }
        if(cl && (!cr || a[l]<a[r])){ last=a[l++]; s+='L'; }
        else if(cr){ last=a[r--]; s+='R'; }
        else break;
    }
    cout<<s.size()<<"\n"<<s<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
// swap any two chars costs A, flip costs B; returns min string (compare lexicographically)
string solve(string s,long long C,long long A,long long B){
    int n=s.size(), ones=count(s.begin(),s.end(),'1'); string best=s;
    for(long long f=0; f<=ones && f*B<=C; f++){        // f = number of flips
        long long sw=(C-f*B)/A; string t=s; int i=0,j=n-1;
        while(sw>0){                                    // leftmost 1 <-> rightmost 0
            while(i<n&&t[i]!='1')i++;
            while(j>=0&&t[j]!='0')j--;
            if(i>=j)break; swap(t[i],t[j]); sw--;
        }
        long long ff=f; for(int k=0;k<n&&ff>0;k++) if(t[k]=='1'){t[k]='0';ff--;} // flip highest 1s
        best=min(best,t);
    }
    return best;
}
int main(){
    int n; string s; long long C,A,B; cin>>n>>s>>C>>A>>B;
    string t=solve(s,C,A,B); const long long M=1e9+7; long long v=0;
    for(char c:t) v=(v*2+(c-'0'))%M;
    cout<<v<<"\n";
}

