#include <bits/stdc++.h>
using namespace std;
// assumes distinct values (with duplicates partners are ambiguous)
int main(){
    int m; cin>>m; vector<long long>a(m); for(auto&x:a)cin>>x;   // m = 2N
    vector<long long> s=a; sort(s.begin(),s.end());
    unordered_map<long long,long long> partner;                  // k-th smallest <-> k-th largest
    for(int i=0;i<m;i++) partner[s[i]]=s[m-1-i];
    unordered_map<long long,int> pos; for(int i=0;i<m;i++) pos[a[i]]=i;
    int swaps=0;
    for(int i=0;i<m;i+=2){
        long long want=partner[a[i]];
        if(a[i+1]!=want){                                        // bring partner next to a[i]
            int j=pos[want];
            pos[a[i+1]]=j; pos[want]=i+1;
            swap(a[i+1],a[j]); swaps++;
        }
    }
    cout<<swaps<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin>>n; vector<long long>S(n); for(auto&x:S)cin>>x;
    vector<long long> diff(n+2,0); long long cur=0, ans=0;
    for(int i=0;i<n;i++){
        cur+=diff[i];                                  // passes arriving at i
        long long need=max(0LL,S[i]-1-cur); ans+=need;
        if(S[i]>=2){ int l=i+2; int r=(int)min<long long>(n-1,i+S[i]);
            if(l<=r){diff[l]++; diff[r+1]--;} }       // jumps of length S..2
        long long extra=cur-(S[i]-1);                  // strength-1 passes -> i+1
        if(extra>0){diff[i+1]+=extra; diff[i+2]-=extra;}
    }
    cout<<ans%1000000007<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
int n; vector<long long> bit;
void upd(int i,long long v){for(i++;i<=n;i+=i&-i)bit[i]+=v;}
long long pre(int i){long long s=0;for(;i>0;i-=i&-i)s+=bit[i];return s;} // sum [0,i)
int main(){
    cin>>n; vector<int>pos(n+1); bit.assign(n+1,0); long long total=0;
    for(int i=0;i<n;i++){int v;cin>>v;pos[v]=i;upd(i,v);total+=v;}
    long long ans=0; int top=0;
    for(int x=1;x<=n;x++){
        int p=pos[x];
        long long fwd = p>=top ? pre(p)-pre(top) : (pre(n)-pre(top))+pre(p);
        ans += min(fwd, total-fwd);
        upd(p,-x); total-=x; top=p;
    }
    cout<<ans%1000000007<<"\n";
}

