using namespace std;
vector<int> twoSum(const vector<int>& a,int target){
    unordered_map<int,int> seen;
    for(int i=0;i<(int)a.size();i++){
        auto it=seen.find(target-a[i]);
        if(it!=seen.end()) return {it->second,i};
        seen[a[i]]=i;
    }
    return {};
}
