#include <bits/stdc++.h>
using namespace std;
class MyHashMap {
    static const int M=10007; vector<list<pair<int,int>>> b;
    int h(int k){ return ((k%M)+M)%M; }
public:
    MyHashMap():b(M){}
    void put(int k,int v){ for(auto&p:b[h(k)]) if(p.first==k){p.second=v;return;} b[h(k)].push_back({k,v}); }
    int get(int k){ for(auto&p:b[h(k)]) if(p.first==k) return p.second; return -1; }
    void remove(int k){ b[h(k)].remove_if([&](auto&p){return p.first==k;}); }
};
int main(){ MyHashMap m; m.put(1,10); m.put(10008,20); cout<<m.get(1)<<" "<<m.get(10008)<<"\n"; m.remove(1); cout<<m.get(1)<<"\n"; }

