vector<vector<string>> groupAnagrams(const vector<string>& w){
    unordered_map<string,vector<string>> g;
    for(auto& s:w){
        int c[26]={0}; for(char ch:s) c[ch-'a']++;
        string key; for(int i=0;i<26;i++){ key+='#'; key+=to_string(c[i]); }
        g[key].push_back(s);
    }
    vector<vector<string>> res; for(auto&p:g) res.push_back(p.second); return res;
}
