#include <bits/stdc++.h>
using namespace std;
class MyHashMap {
    static const int M=200003; vector<int> K,V; vector<char> S;     // S: 0 empty,1 used,2 deleted
    int h(int k){ return (int)(((long long)k%M+M)%M); }
public:
    MyHashMap():K(M),V(M),S(M,0){}
    void put(int k,int v){
        int i=h(k), tomb=-1;
        while(S[i]!=0){ if(S[i]==1&&K[i]==k){V[i]=v;return;} if(S[i]==2&&tomb<0) tomb=i; i=(i+1)%M; }
        if(tomb>=0) i=tomb; K[i]=k; V[i]=v; S[i]=1;
    }
    int get(int k){ for(int i=h(k);S[i]!=0;i=(i+1)%M) if(S[i]==1&&K[i]==k) return V[i]; return -1; }
    void remove(int k){ for(int i=h(k);S[i]!=0;i=(i+1)%M) if(S[i]==1&&K[i]==k){S[i]=2;return;} }
};
int main(){ MyHashMap m; m.put(1,1); m.put(200004,2); m.remove(1); cout<<m.get(200004)<<" "<<m.get(1)<<"\n"; }

#include <bits/stdc++.h>
using namespace std;
vector<int> topKFrequent(const vector<int>& a,int k){
    unordered_map<int,int> f; for(int x:a) f[x]++;
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<>> pq;   // min-heap by freq
    for(auto&[v,c]:f){ pq.push({c,v}); if((int)pq.size()>k) pq.pop(); }
    vector<int> r; while(!pq.empty()){ r.push_back(pq.top().second); pq.pop(); }
    reverse(r.begin(),r.end()); return r;
}
int main(){ for(int x:topKFrequent({1,1,1,2,2,3},2)) cout<<x<<" "; cout<<"\n"; }

