long long countSubarrays(const vector<long long>& a,long long T){
    unordered_map<long long,long long> cnt; cnt[0]=1; long long P=0, ans=0;
    for(long long x:a){ P+=x; auto it=cnt.find(P-T); if(it!=cnt.end()) ans+=it->second; cnt[P]++; }
