using namespace std;
int subarraySum(const vector<int>& a,int k){
    unordered_map<long long,int> cnt; cnt[0]=1; long long P=0; int ans=0;
    for(int x:a){ P+=x; if(cnt.count(P-k)) ans+=cnt[P-k]; cnt[P]++; }
    return ans;
}
