#include <bits/stdc++.h>
using namespace std;
long long countPairs(const vector<int>& a,long long k){
    unordered_map<int,long long> cnt; long long ans=0; int n=a.size();
    for(int j=0;j<n;j++){
        if(j-k-1>=0) cnt[a[j-k-1]]--;          // keep window [j-k, j-1]
        ans+=cnt[a[j]]; cnt[a[j]]++;
    }
    return ans;
}
