#include <bits/stdc++.h>
using namespace std;
class LRUCache {
    int cap; list<pair<int,int>> dll;                        // front = most recent
    unordered_map<int, list<pair<int,int>>::iterator> mp;
public:
    LRUCache(int c):cap(c){}
    int get(int k){
        auto it=mp.find(k); if(it==mp.end()) return -1;
        dll.splice(dll.begin(), dll, it->second);           // move to front, O(1)
        return it->second->second;
    }
    void put(int k,int v){
        auto it=mp.find(k);
        if(it!=mp.end()){ it->second->second=v; dll.splice(dll.begin(),dll,it->second); return; }
        if((int)dll.size()==cap){ mp.erase(dll.back().first); dll.pop_back(); } // evict LRU
        dll.emplace_front(k,v); mp[k]=dll.begin();
    }
};
int main(){
    LRUCache c(2); c.put(1,1); c.put(2,2); cout<<c.get(1)<<" "; c.put(3,3);
    cout<<c.get(2)<<" "<<c.get(3)<<"\n";                    // 1 -1 3
}

