#include <bits/stdc++.h>
using namespace std;
class LFUCache {
    int cap, minF=0;
    unordered_map<int,pair<int,int>> kv;                 // key -> (value, freq)
    unordered_map<int,list<int>> lists;                  // freq -> keys (front = recent)
    unordered_map<int,list<int>::iterator> pos;
    void touch(int k){
        int f=kv[k].second; lists[f].erase(pos[k]);
        if(lists[f].empty() && minF==f) minF++;
        kv[k].second++; lists[f+1].push_front(k); pos[k]=lists[f+1].begin();
    }
public:
    LFUCache(int c):cap(c){}
    int get(int k){ if(!kv.count(k)) return -1; touch(k); return kv[k].first; }
    void put(int k,int v){
        if(cap<=0) return;
        if(kv.count(k)){ kv[k].first=v; touch(k); return; }
        if((int)kv.size()==cap){ int e=lists[minF].back(); lists[minF].pop_back(); kv.erase(e); pos.erase(e); }
        kv[k]={v,1}; lists[1].push_front(k); pos[k]=lists[1].begin(); minF=1;
    }
};
int main(){ LFUCache c(2); c.put(1,1); c.put(2,2); cout<<c.get(1)<<" "; c.put(3,3); cout<<c.get(2)<<" "<<c.get(3)<<"\n"; }

