using namespace std;
void bubbleSort(vector<int>& a){
    int n=a.size();
    for(int i=0;i<n-1;i++){
        bool swapped=false;
        for(int j=0;j<n-1-i;j++)              // largest of the unsorted part bubbles to the end
            if(a[j]>a[j+1]){ swap(a[j],a[j+1]); swapped=true; }
        if(!swapped) break;                   // already sorted -> O(n) best case
    }
}
