#include <bits/stdc++.h>
using namespace std;
int partition(vector<int>& a,int lo,int hi){          // Lomuto, pivot = last
    int p=a[hi], i=lo;
    for(int j=lo;j<hi;j++) if(a[j]<p) swap(a[i++],a[j]);
    swap(a[i],a[hi]); return i;
}
void quickSort(vector<int>& a,int lo,int hi){
    if(lo>=hi) return;
    swap(a[lo+rand()%(hi-lo+1)],a[hi]);               // random pivot avoids O(n^2) on sorted input
    int p=partition(a,lo,hi);
    quickSort(a,lo,p-1); quickSort(a,p+1,hi);
}
