void mergeSort(vector<int>& a,int l,int r,vector<int>& tmp){   // sorts a[l..r]
    if(l>=r) return;
    int m=(l+r)/2; mergeSort(a,l,m,tmp); mergeSort(a,m+1,r,tmp);
    int i=l,j=m+1,k=l;
    while(i<=m&&j<=r) tmp[k++]= a[i]<=a[j]? a[i++] : a[j++];  // <= keeps it stable
    while(i<=m) tmp[k++]=a[i++];
    while(j<=r) tmp[k++]=a[j++];
    for(k=l;k<=r;k++) a[k]=tmp[k];
}
