#include <bits/stdc++.h>
using namespace std;
const long long MOD=1e9+7;
int main(){
    int n,K; cin>>n; vector<vector<int>> ch(n); int root=0;
    for(int i=0;i<n;i++){int p;cin>>p; if(p<0) root=i; else ch[p].push_back(i);} cin>>K;
    vector<int> order={root}; for(size_t i=0;i<order.size();i++) for(int c:ch[order[i]]) order.push_back(c);
    vector<vector<long long>> dp(n);
    for(int idx=n-1;idx>=0;idx--){
        int v=order[idx]; vector<long long> cur(K+1,0); cur[0]=1; cur[K]+=1;   // black / white
        for(int c:ch[v]){
            vector<long long> nw(K+1,0);
            for(int a=0;a<=K;a++) if(cur[a]) for(int b=0;b<=K;b++) if(dp[c][b]){
                int b2=min(b+1,K); if(a+b2<K) continue;
                int d=min(a,b2); nw[d]=(nw[d]+cur[a]*dp[c][b])%MOD;
            }
            cur=nw; vector<long long>().swap(dp[c]);
        }
        dp[v]=cur;
    }
    long long ans=0; for(auto x:dp[root]) ans=(ans+x)%MOD; cout<<ans<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
int n,LOG=1; vector<vector<int>> g,up; vector<int> tin,tout,dep;
long long inter(int l1,int r1,int l2,int r2){ return max(0,min(r1,r2)-max(l1,l2)); }
int jump(int v,int k){ for(int j=0;j<LOG;j++) if(k>>j&1) v=up[j][v]; return v; }
long long query(int U,int V,int B){              // |subtree_A(U) ∩ subtree_B(V)|
    long long su=tout[U]-tin[U];
    if(V==B) return su;                          // whole tree
    if(!(tin[V]<=tin[B]&&tin[B]<tout[V])) return inter(tin[U],tout[U],tin[V],tout[V]);
    int c=jump(B,dep[B]-dep[V]-1);               // child of V toward B
    return su - inter(tin[U],tout[U],tin[c],tout[c]);   // all minus subtree_A(c)
}
int main(){
    int A,B; cin>>n>>A>>B; g.assign(n+1,{});
    for(int i=1;i<=n;i++){int p;cin>>p; if(p){g[p].push_back(i);g[i].push_back(p);}}
    while((1<<LOG)<=n) LOG++;
    up.assign(LOG,vector<int>(n+1,A)); tin.assign(n+1,0); tout=tin; dep=tin;
    int T=0; vector<pair<int,int>> st={{A,0}};
    while(!st.empty()){ auto &[v,i]=st.back();          // iterative DFS rooted at A
        if(i==0) tin[v]=T++;
        if(i<(int)g[v].size()){ int w=g[v][i++]; if(w==up[0][v]&&v!=A) continue; if(w==A) continue;
            up[0][w]=v; dep[w]=dep[v]+1; st.push_back({w,0}); }
        else { tout[v]=T; st.pop_back(); } }
    for(int j=1;j<LOG;j++) for(int v=1;v<=n;v++) up[j][v]=up[j-1][up[j-1][v]];
    int q; cin>>q; long long sum=0, last=0;
    while(q--){ int u,v; cin>>u>>v; /* decode u,v with last per statement */ last=query(u,v,B); sum+=last; }
    cout<<sum%1000000007<<"\n";
}

