using namespace std;
int n,LOG=1; vector<vector<int>> g,up; vector<int> tin,tout,dep;
long long inter(int l1,int r1,int l2,int r2){ return max(0,min(r1,r2)-max(l1,l2)); }
int jump(int v,int k){ for(int j=0;j<LOG;j++) if(k>>j&1) v=up[j][v]; return v; }
long long query(int U,int V,int B){              // |subtree_A(U) ∩ subtree_B(V)|
    long long su=tout[U]-tin[U];
    if(V==B) return su;                          // whole tree
    if(!(tin[V]<=tin[B]&&tin[B]<tout[V])) return inter(tin[U],tout[U],tin[V],tout[V]);
    int c=jump(B,dep[B]-dep[V]-1);               // child of V toward B
    return su - inter(tin[U],tout[U],tin[c],tout[c]);   // all minus subtree_A(c)
}
