using namespace std;
void mergeGap(vector<int>& a, vector<int>& b){
    int n=a.size(), m=b.size(), len=n+m, gap=(len+1)/2;
    auto at=[&](int k)->int&{ return k<n? a[k] : b[k-n]; };
    while(gap>0){
        for(int i=0;i+gap<len;i++) if(at(i)>at(i+gap)) swap(at(i),at(i+gap));
        if(gap==1) break; gap=(gap+1)/2;
    }
}
int main(){ vector<int>a={1,4,7},b={2,3,9}; mergeGap(a,b); for(int x:a)cout<<x<<" "; cout<<"| "; for(int x:b)cout<<x<<" "; cout<<"\n"; }

#include <bits/stdc++.h>
using namespace std;
int longestBalanced(const string& s,int k){
    int n=s.size(), V=2*n+1; vector<int> first(V,INT_MAX), P(n+1,0); first[n]=0;
    for(int i=1;i<=n;i++){ P[i]=P[i-1]+(s[i-1]=='1'?1:-1); first[P[i]+n]=min(first[P[i]+n],i); }
    int LOG=1; while((1<<LOG)<=V) LOG++;
    vector<vector<int>> sp(LOG,first);
    for(int j=1;j<LOG;j++) for(int i=0;i+(1<<j)<=V;i++) sp[j][i]=min(sp[j-1][i],sp[j-1][i+(1<<(j-1))]);
    auto qmin=[&](int l,int r){ int j=31-__builtin_clz(r-l+1); return min(sp[j][l],sp[j][r-(1<<j)+1]); };
    int best=0;
    for(int j=1;j<=n;j++){
        int lo=max(-n,P[j]-2*k), hi=min(n,P[j]+2*k), i=qmin(lo+n,hi+n);
        if(i<=j){ int len=j-i; if(len&1) len--; best=max(best,len); }
    }
    return best;
}
int main(){ string s; int k; cin>>s>>k; cout<<longestBalanced(s,k)<<"\n"; }

