long long trap(const vector<long long>& h){
    int l=0,r=(int)h.size()-1; long long lm=0,rm=0,w=0;
    while(l<r){
        if(h[l]<h[r]){ lm=max(lm,h[l]); w+=lm-h[l]; l++; }
