long long countProductAtLeast(const vector<long long>& a,long long K){
    long long n=a.size(), less=0; long double prod=1; int l=0;
    for(int r=0;r<n;r++){
        prod*=a[r];
        while(l<=r && prod>=K) prod/=a[l++];
        less+=r-l+1;
    }
    return n*(n+1)/2 - less;
}
