using namespace std;
int minWithdrawals(const vector<long long>& a,long long X){
    long long total=accumulate(a.begin(),a.end(),0LL), target=total-X; int n=a.size();
    if(target<0) return -1; if(target==0) return n;
    long long s=0; int l=0,best=-1;
    for(int r=0;r<n;r++){ s+=a[r]; while(s>target) s-=a[l++]; if(s==target) best=max(best,r-l+1); }
    return best<0? -1 : n-best;
}
