long long maxSumKDistinct(const vector<long long>& a,int k){
    int n=a.size(); vector<long long> P(n+1,0); for(int i=0;i<n;i++) P[i+1]=P[i]+a[i];
    unordered_map<long long,int> cnt; deque<int> dq; long long best=0; int L=0;
    for(int r=0;r<n;r++){
        cnt[a[r]]++;
        while((int)cnt.size()>k){ if(--cnt[a[L]]==0) cnt.erase(a[L]); L++; }
        while(!dq.empty()&&P[dq.back()]>=P[r]) dq.pop_back(); dq.push_back(r);
        while(dq.front()<L) dq.pop_front();
        if(L<=r) best=max(best,P[r+1]-P[dq.front()]);
    }
    return best;
}
