#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,W,K; long long D; cin>>n>>W>>K>>D; vector<long long>s(n);
    for(auto&x:s){ cin>>x; x=min(x,D); }                    // saving if a coupon is used
    multiset<long long> top,rest; long long sum=0,best=0;    // top = K largest in window
    auto fix=[&](){
        while((int)top.size()>K){ auto it=top.begin(); sum-=*it; rest.insert(*it); top.erase(it); }
        while((int)top.size()<K && !rest.empty()){ auto it=prev(rest.end()); sum+=*it; top.insert(*it); rest.erase(it); }
        while(!rest.empty()&&!top.empty()&&*prev(rest.end())>*top.begin()){
            auto a=prev(rest.end()); auto b=top.begin(); long long x=*a,y=*b;
            rest.erase(a); top.erase(b); top.insert(x); rest.insert(y); sum+=x-y; }
    };
    for(int i=0;i<n;i++){
        top.insert(s[i]); sum+=s[i];
        if(i>=W){ long long x=s[i-W]; auto it=top.find(x);
            if(it!=top.end()){ top.erase(it); sum-=x; } else rest.erase(rest.find(x)); }
        fix(); if(i>=W-1) best=max(best,sum);
    }
    cout<<best%1000000007<<"\n";
}

