#include <bits/stdc++.h>
using namespace std;
int smallestWithKPairs(const vector<long long>& a,long long K){
    int n=a.size(), l=0, best=INT_MAX; long long ev=0,od=0,pairs=0;
    for(int r=0;r<n;r++){
        if(a[r]%2==0) ev++; else { pairs+=ev; od++; }
        while(l<=r && pairs>=K){
            best=min(best,r-l+1);
            if(a[l]%2==0){ pairs-=od; ev--; } else od--;
            l++;
        }
    }
    return best==INT_MAX? -1 : best;
}
